output_text:
[
  {
    "id": "take_entrance_cart",
    "text": "A shopper is obliged to check out the entrance cart before continuing the trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": "at(1,5)",
        "has_trolley": "hasCart"
      },
      "events": {
        "check_out_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "has_trolley"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "check_out_cart"
    }
  },
  {
    "id": "no_hand_shopping",
    "text": "Items should not be carried by hand; any item pickup must be made while the shopper has the cart.",
    "abstraction": {
      "state_properties": {
        "has_trolley": "hasCart",
        "carrying_by_hand": "handFull"
      },
      "events": {
        "pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "has_trolley"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "pickup_without_cart"
        ]
      }
    }
  },
  {
    "id": "return_checked_out_cart",
    "text": "Once a shopper takes a cart, they are obliged to return it to the customer-service return point.",
    "abstraction": {
      "state_properties": {
        "customer_service_cart_return": "at(0,1)",
        "cart_returned_to_service": "cartAt(0,1)"
      },
      "events": {
        "cart_taken": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "cart_returned": {
          "pre": {
            "and": [
              "customer_service_cart_return",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_returned_to_service"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_taken",
      "discharge": "cart_returned"
    }
  },
  {
    "id": "only_leave_cart_at_service",
    "text": "A cart may only be put down at the designated customer-service cart return at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "customer_service_cart_return": "at(0,1)",
        "outside_cart_return": {
          "not": "customer_service_cart_return"
        }
      },
      "events": {
        "leave_cart_outside_return": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "outside_cart_return"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_return"
    }
  },
  {
    "id": "exit_only_after_cart_return",
    "text": "A shopper must not exit the store until the cart has been returned to the cart-return point.",
    "abstraction": {
      "state_properties": {
        "cart_returned_to_service": "cartAt(0,1)",
        "still_with_cart": "hasCart"
      },
      "events": {
        "attempt_exit": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "attempt_exit",
          {
            "or": [
              "still_with_cart",
              {
                "not": "cart_returned_to_service"
              }
            ]
          }
        ]
      }
    }
  },
  {
    "id": "no_carts_in_checkout_lane",
    "text": "Shopping carts are prohibited in the checkout and exit-approach lanes on the right side of the store.",
    "abstraction": {
      "state_properties": {
        "checkout_or_exit_lane": {
          "or": [
            "at(7,1)",
            "at(8,1)",
            "at(9,1)",
            "at(7,2)",
            "at(8,2)",
            "at(9,2)",
            "at(7,3)",
            "at(8,3)",
            "at(9,3)",
            "at(7,4)",
            "at(8,4)",
            "at(9,4)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "cart_in_checkout_lane": {
          "and": [
            "hasCart",
            "checkout_or_exit_lane"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_checkout_lane"
    }
  },
  {
    "id": "return_cart_after_item_loading",
    "text": "After any item is loaded into the cart, the loaded cart must eventually be returned to the customer-service cart return.",
    "abstraction": {
      "state_properties": {
        "customer_service_cart_return": "at(0,1)",
        "cart_returned_to_service": "cartAt(0,1)"
      },
      "events": {
        "item_loaded_into_cart": {
          "pre": {
            "and": [
              "hasCart",
              "PICKUP_ITEM"
            ]
          },
          "post": "hasCart"
        },
        "loaded_cart_returned": {
          "pre": {
            "and": [
              "customer_service_cart_return",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_returned_to_service"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "item_loaded_into_cart",
      "discharge": "loaded_cart_returned"
    }
  },
  {
    "id": "no_east_from_far_shelf_with_cart",
    "text": "At the far shelf position, a shopper pushing a cart must not continue east and should turn back into the aisle.",
    "abstraction": {
      "state_properties": {
        "far_shelf_position": "at(6,4)",
        "with_cart_at_far_shelf": {
          "and": [
            "far_shelf_position",
            "hasCart"
          ]
        }
      },
      "events": {
        "push_cart_east_from_far_shelf": {
          "pre": {
            "and": [
              "with_cart_at_far_shelf",
              "E"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "push_cart_east_from_far_shelf"
    }
  }
]
